CREATE TABLE public.governance_settings(id integer PRIMARY KEY CHECK(id=1),max_priorities integer NOT NULL DEFAULT 3,council_seats integer NOT NULL DEFAULT 31,study_minutes integer NOT NULL DEFAULT 60,negotiation_minutes integer NOT NULL DEFAULT 45,vote_minutes integer NOT NULL DEFAULT 60,energy_cost integer NOT NULL DEFAULT 8,initial_budget bigint NOT NULL DEFAULT 2000000,monthly_income bigint NOT NULL DEFAULT 250000,monthly_expense bigint NOT NULL DEFAULT 180000,reserve bigint NOT NULL DEFAULT 100000,consultation_hours integer NOT NULL DEFAULT 24,event_hour integer NOT NULL DEFAULT 18);
GRANT SELECT ON public.governance_settings TO authenticated; GRANT ALL ON public.governance_settings TO service_role; ALTER TABLE public.governance_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY governance_settings_read ON public.governance_settings FOR SELECT TO authenticated USING(true);
CREATE TABLE public.governance_rules(id text PRIMARY KEY,title text NOT NULL,objective text NOT NULL,indicator text NOT NULL,category text NOT NULL,location_kind text NOT NULL,cost bigint NOT NULL CHECK(cost>0),duration_days integer NOT NULL CHECK(duration_days>0),immediate jsonb NOT NULL DEFAULT '{}',completion jsonb NOT NULL DEFAULT '{}',delayed jsonb NOT NULL DEFAULT '{}',delayed_days integer NOT NULL DEFAULT 7,axis text NOT NULL,target integer NOT NULL CHECK(target BETWEEN 0 AND 100),risk integer NOT NULL DEFAULT 0 CHECK(risk BETWEEN 0 AND 100),failure_delta jsonb NOT NULL DEFAULT '{"satisfaction":-3}',reputation_gain integer NOT NULL DEFAULT 3,influence_gain integer NOT NULL DEFAULT 1);
GRANT SELECT ON public.governance_rules TO authenticated; GRANT ALL ON public.governance_rules TO service_role; ALTER TABLE public.governance_rules ENABLE ROW LEVEL SECURITY; CREATE POLICY governance_rules_read ON public.governance_rules FOR SELECT TO authenticated USING(true);
CREATE TABLE public.city_indicators(city_id text REFERENCES public.cities(id),indicator text NOT NULL,value integer NOT NULL CHECK(value BETWEEN 0 AND 100),baseline integer NOT NULL CHECK(baseline BETWEEN 0 AND 100),PRIMARY KEY(city_id,indicator));
GRANT SELECT ON public.city_indicators TO authenticated; GRANT ALL ON public.city_indicators TO service_role; ALTER TABLE public.city_indicators ENABLE ROW LEVEL SECURITY; CREATE POLICY city_indicators_read ON public.city_indicators FOR SELECT TO authenticated USING(true);
CREATE TABLE public.municipal_treasuries(city_id text PRIMARY KEY REFERENCES public.cities(id),balance bigint NOT NULL CHECK(balance>=0),reserve bigint NOT NULL CHECK(reserve>=0),income bigint NOT NULL DEFAULT 0,expenses bigint NOT NULL DEFAULT 0,last_period integer NOT NULL DEFAULT 0,anchor timestamptz NOT NULL DEFAULT public.game_now());
GRANT SELECT ON public.municipal_treasuries TO authenticated; GRANT ALL ON public.municipal_treasuries TO service_role; ALTER TABLE public.municipal_treasuries ENABLE ROW LEVEL SECURITY; CREATE POLICY municipal_treasuries_read ON public.municipal_treasuries FOR SELECT TO authenticated USING(true);
ALTER TABLE public.municipal_mandates ADD COLUMN priorities text[] NOT NULL DEFAULT '{}',ADD COLUMN opening_indicators jsonb NOT NULL DEFAULT '{}',ADD COLUMN closing_indicators jsonb,ADD COLUMN opening_politics jsonb NOT NULL DEFAULT '{}',ADD COLUMN closing_politics jsonb,ADD COLUMN governance_initialized_at timestamptz,ADD COLUMN final_report jsonb;
ALTER TABLE public.public_decisions ADD COLUMN mandate_id uuid REFERENCES public.municipal_mandates(id) ON DELETE CASCADE,ADD COLUMN governance_rule_id text REFERENCES public.governance_rules(id),ADD COLUMN workflow text,ADD COLUMN objective text,ADD COLUMN cost bigint,ADD COLUMN duration_days integer,ADD COLUMN impact_expected jsonb,ADD COLUMN impact_real jsonb NOT NULL DEFAULT '{}',ADD COLUMN rule_snapshot jsonb,ADD COLUMN studied_at timestamptz,ADD COLUMN proposed_at timestamptz,ADD COLUMN voted_at timestamptz,ADD COLUMN council_result jsonb,ADD COLUMN funded_at timestamptz,ADD COLUMN ends_at timestamptz,ADD COLUMN completed_at timestamptz,ADD COLUMN failure boolean NOT NULL DEFAULT false,ADD COLUMN delay_days integer NOT NULL DEFAULT 0,ADD COLUMN compromise boolean NOT NULL DEFAULT false,ADD COLUMN political_settled_at timestamptz;
ALTER TABLE public.public_decisions ADD CONSTRAINT governance_workflow CHECK(workflow IS NULL OR workflow IN('idea','study','proposed','approved','rejected','running','completed','abandoned'));
CREATE INDEX governance_city_projects ON public.public_decisions(city_id,workflow) WHERE mandate_id IS NOT NULL;
ALTER TABLE public.public_issues ADD COLUMN governance_managed boolean NOT NULL DEFAULT false,ADD COLUMN indicator text,ADD COLUMN governance_delta integer NOT NULL DEFAULT 0;
ALTER TABLE public.consultations ADD COLUMN advisory boolean NOT NULL DEFAULT false,ADD COLUMN governance_decision_id uuid REFERENCES public.public_decisions(id) ON DELETE CASCADE;
CREATE TABLE public.municipal_council_groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),mandate_id uuid NOT NULL REFERENCES public.municipal_mandates(id) ON DELETE CASCADE,organization_id uuid REFERENCES public.organizations(id),candidate_id uuid REFERENCES public.candidacies(id) ON DELETE CASCADE,name text NOT NULL,seats integer NOT NULL CHECK(seats>=0),majority boolean NOT NULL DEFAULT false,ideology jsonb NOT NULL DEFAULT '{}',leader_id uuid REFERENCES public.social_npcs(id),base_support integer NOT NULL DEFAULT 40 CHECK(base_support BETWEEN 0 AND 100),UNIQUE(mandate_id,candidate_id));
GRANT SELECT ON public.municipal_council_groups TO authenticated; GRANT ALL ON public.municipal_council_groups TO service_role; ALTER TABLE public.municipal_council_groups ENABLE ROW LEVEL SECURITY; CREATE POLICY municipal_council_read ON public.municipal_council_groups FOR SELECT TO authenticated USING(true);
CREATE TABLE public.municipal_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city_id text NOT NULL REFERENCES public.cities(id),entry_key text NOT NULL UNIQUE,decision_id uuid REFERENCES public.public_decisions(id) ON DELETE CASCADE,category text NOT NULL,amount bigint NOT NULL,label text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT public.game_now());
GRANT SELECT ON public.municipal_ledger TO authenticated; GRANT ALL ON public.municipal_ledger TO service_role; ALTER TABLE public.municipal_ledger ENABLE ROW LEVEL SECURITY; CREATE POLICY municipal_ledger_read ON public.municipal_ledger FOR SELECT TO authenticated USING(true);
CREATE TABLE public.governance_effects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),decision_id uuid NOT NULL REFERENCES public.public_decisions(id) ON DELETE CASCADE,effect_key text NOT NULL UNIQUE,due_at timestamptz NOT NULL,deltas jsonb NOT NULL,kind text NOT NULL,applied_at timestamptz);
GRANT SELECT ON public.governance_effects TO authenticated; GRANT ALL ON public.governance_effects TO service_role; ALTER TABLE public.governance_effects ENABLE ROW LEVEL SECURITY; CREATE POLICY governance_effects_read ON public.governance_effects FOR SELECT TO authenticated USING(true);
CREATE INDEX governance_due_effects ON public.governance_effects(due_at) WHERE applied_at IS NULL;
CREATE TABLE public.indicator_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city_id text REFERENCES public.cities(id),indicator text NOT NULL,before_value integer NOT NULL,after_value integer NOT NULL,effect_key text NOT NULL,occurred_at timestamptz NOT NULL,UNIQUE(effect_key,indicator));
GRANT SELECT ON public.indicator_history TO authenticated; GRANT ALL ON public.indicator_history TO service_role; ALTER TABLE public.indicator_history ENABLE ROW LEVEL SECURITY; CREATE POLICY indicator_history_read ON public.indicator_history FOR SELECT TO authenticated USING(true);
CREATE TABLE public.governance_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),decision_id uuid NOT NULL REFERENCES public.public_decisions(id) ON DELETE CASCADE,character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,activity_id uuid UNIQUE REFERENCES public.activities(id) ON DELETE CASCADE,command text NOT NULL CHECK(command IN('study','negotiate','vote')),group_id uuid REFERENCES public.municipal_council_groups(id) ON DELETE CASCADE,compromise boolean NOT NULL DEFAULT false,settled_at timestamptz,UNIQUE(decision_id,command,group_id));
CREATE UNIQUE INDEX governance_single_study_vote ON public.governance_actions(decision_id,command) WHERE command IN('study','vote');
GRANT SELECT ON public.governance_actions TO authenticated; GRANT ALL ON public.governance_actions TO service_role; ALTER TABLE public.governance_actions ENABLE ROW LEVEL SECURITY; CREATE POLICY governance_actions_owner ON public.governance_actions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.governance_positions(decision_id uuid REFERENCES public.public_decisions(id) ON DELETE CASCADE,group_id uuid REFERENCES public.municipal_council_groups(id) ON DELETE CASCADE,support integer NOT NULL CHECK(support BETWEEN 0 AND 100),negotiated boolean NOT NULL DEFAULT false,reaction text NOT NULL,PRIMARY KEY(decision_id,group_id));
GRANT SELECT ON public.governance_positions TO authenticated; GRANT ALL ON public.governance_positions TO service_role; ALTER TABLE public.governance_positions ENABLE ROW LEVEL SECURITY; CREATE POLICY governance_positions_read ON public.governance_positions FOR SELECT TO authenticated USING(true);
CREATE TABLE public.governance_reactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city_id text NOT NULL REFERENCES public.cities(id),decision_id uuid REFERENCES public.public_decisions(id) ON DELETE CASCADE,reaction_key text NOT NULL UNIQUE,kind text NOT NULL,title text NOT NULL,description text NOT NULL,occurred_at timestamptz NOT NULL,news_id uuid REFERENCES public.news(id));
GRANT SELECT ON public.governance_reactions TO authenticated; GRANT ALL ON public.governance_reactions TO service_role; ALTER TABLE public.governance_reactions ENABLE ROW LEVEL SECURITY; CREATE POLICY governance_reactions_read ON public.governance_reactions FOR SELECT TO authenticated USING(true);
CREATE TABLE public.governance_periods(city_id text REFERENCES public.cities(id),period integer NOT NULL,occurred_at timestamptz NOT NULL,PRIMARY KEY(city_id,period));
GRANT SELECT ON public.governance_periods TO authenticated; GRANT ALL ON public.governance_periods TO service_role; ALTER TABLE public.governance_periods ENABLE ROW LEVEL SECURITY; CREATE POLICY governance_periods_read ON public.governance_periods FOR SELECT TO authenticated USING(true);
ALTER TABLE public.activities ADD COLUMN governance_action_id uuid REFERENCES public.governance_actions(id) ON DELETE SET NULL;
COMMENT ON COLUMN public.public_decisions.workflow IS 'Governance procedure and project lifecycle; historical status remains planned/applied for authorized physical effects only.';